using Microsoft.AspNetCore.Authorization; using Microsoft.AspNetCore.Identity; using Microsoft.AspNetCore.Mvc; using Microsoft.EntityFrameworkCore; using StudentAccommodationSystem.Data; using StudentAccommodationSystem.Models;
namespace StudentAccommodationSystem.Controllers;
[Authorize(Roles="Student")] public class ReviewController(ApplicationDbContext db,UserManager<ApplicationUser> users):Controller
{ [HttpGet] public IActionResult Create(int propertyId)=>View(new Review{PropertyId=propertyId}); [HttpPost,ValidateAntiForgeryToken] public async Task<IActionResult> Create(Review r){var u=await users.GetUserAsync(User);var s=await db.StudentProfiles.FirstAsync(x=>x.UserId==u!.Id);var eligible=await db.RentalAgreements.AnyAsync(x=>x.StudentProfileId==s.Id&&x.PropertyId==r.PropertyId&&x.Status==AgreementStatus.Expired || (x.Status==AgreementStatus.Active && x.EndDate<DateTime.UtcNow));if(!eligible){ModelState.AddModelError("","A completed/expired stay is required before reviewing.");return View(r);}r.StudentProfileId=s.Id;db.Reviews.Add(r);await db.SaveChangesAsync();return RedirectToAction("Details","Property",new{id=r.PropertyId});}}
